class Spieler extends Sprite {
   Spieler() {
      super(400, 700, SpriteLibrary.PMan, 5);
      scale(1.5);
   }

   void geheNachRechts()
   {
      move(10, 0);
   }

   void geheNachLinks()
   {
      move(-10, 0);
   }

   void sprinteNachRechts() {
      move(25, 0);
   }

   void sprinteNachLinks() {
      move(-25, 0);
   }

   void act() {
      if(isKeyDown("d") && isKeyDown("ArrowRight")) {
         sprinteNachRechts();
      } 
      else if(isKeyDown("a") && isKeyDown("ArrowLeft")) {
         sprinteNachLinks();
      } 
      else if(isKeyDown("a")) {
         geheNachLinks();
      } 
      else if(isKeyDown("d")) {
         geheNachRechts();
      }
   }
}

class Apfel extends Sprite {

   double fallgeschwindigkeit = 10;

   //TODO 6.1 Referenzattribut für Spiel deklarieren.
   Spiel spiel;

   //Konstruktor
   Apfel(Spiel _spiel/*TODO6.2 Parameter für übergabe der Spielreferenz*/) {
      super(Random.randint(50, 750), 0, SpriteLibrary.PMan, 15);
      scale(1.5);
      // TODO6.3 Referenzattribut gleich Parameter setzen
      spiel = _spiel; 
   }

   public void act() {
      move(0, fallgeschwindigkeit);

      // TODO6.4 Überprüfe, ob das Spieler OBJEKT, 
      // welches ein Attribut der Klasse Spiel ist, kollidiert
      if(collidesWith(spiel.s1)) {
         fallgeschwindigkeit = fallgeschwindigkeit + 1;
         moveTo(Random.randint(50, 750), 0);
      }

      // TODO6.5 Attribut in spiel Objekt auslesen
      if(spiel.anzahlLeben == 0) {
         fallgeschwindigkeit = fallgeschwindigkeit - 10;
         gameOverScreen();
      }

      if(isOutsideView()) {
         //TODO anpassen
         moveTo(Random.randint(50, 750), 0);
         spiel.einLebenAbzug();
      }
   }

   //TODO In Spiel Klasse verschieben

   public void gameOverScreen() {
      new Text(260, 300, 50, "GAME OVER!");
      new Text(180, 400, 50, "Deine Punktzahl ist: " + fallgeschwindigkeit);
      System.exit(1);
   }
}

